{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCSM - Curtis L. Carlson School of Management", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPARationale": "Admission to the Carlson School is competitive and applications far outweigh the number of students we can effectively serve with our faculty resources.  Recent GPA averages have been above a 3.50.", "cdProgramAdmissionGPATrans": true, "cdProgramAdmissionGPATransIUT": true, "cdProgramAdmissionGPATransIUTMin": "3", "cdProgramAdmissionGPATransMin": "3", "cdProgramAdmissionPreMajorStatus": "Yes, freshmen and transfer students", "cdProgramCareer": "Undergraduate", "cdProgramCreditsDegreeMax": "120", "cdProgramCreditsDegreeMin": "120", "cdProgramCreditsProgramMax": 89, "cdProgramCreditsProgramMin": 82, "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "Accounting is the process of gathering financial information and presenting it in a manner that will help users of that information make better decisions. Accountants are also frequently called upon to analyze financial information and provide important business advice. The terms and definitions that have emerged from the discipline are used widely. In fact, accounting is commonly described as the "language of business."

The role of accountants has changed dramatically over the years, and they are recognized as valued business advisors and important members of an organization's management team.

The major areas of study within the accounting curriculum are financial accounting, management accounting, income taxation, auditing, and business law.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Business", "cdProgramLOs": "<ul><li><p>Students can identify, define, and solve problems.</p></li><li><p>Students can locate and critically evaluate information.</p></li><li><p>Students have mastered a body of knowledge and a mode of inquiry.</p></li><li><p>Students understand diverse philosophies and culture within and across societies.</p></li><li><p>Students can communicate effectively.</p></li><li><p>Students understand the role of creativity, innovation, discovery, and expression across disciplines.</p></li><li><p>Students have acquired skills for effective citizenship and lifelong learning.</p></li></ul>", "cdProgramLengthInTermsUndergrad": "8", "cdProgramNameShort": "Acct", "cdProgramReqLanguageUgrd": "No second language", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Baccalaureate", "cdSamplePlanLink": "<p><a rel="noopener noreferrer nofollow" class="open_in_new_tab" href="https://sampleplan.umn.edu/node/726">Accounting B.S.B.</a></p>", "feV9J": "<p>Adding ACCT 4411, which is a cross-listed version of IDSC 4411, as a major elective option.</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Undergraduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCOA - College of Food, Agricultural and Natural Resource Sciences", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionEngTestPref": "Test of English as a Foreign language (TOEFL)", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGPAUgrdMin": "3", "cdProgramAdmissionGRE": true, "cdProgramAdmissionIELTS": true, "cdProgramAdmissionIELTSTotScore": "6.5", "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOthAppReqs": "Applicants must submit scores from the General Test of the GRE, three letters of recommendation from persons familiar with the applicant's scholarship and research potential, a complete set of college or university transcripts, a clearly written statement of academic and career interests, goals, objectives, and a diversity statement. For complete application instructions, visit the website: https://apec.umn.edu/graduate/admissions.

Students should apply by the December 10 to ensure priority consideration for admissions and funding. ", "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": true, "cdProgramAdmissionTOEFLReadScore": "19", "cdProgramAdmissionTOEFLTotScore": "79", "cdProgramAdmissionTOEFLWritScore": "21", "cdProgramCareer": "Graduate", "cdProgramCreditsDegreeMin": 61, "cdProgramCreditsDoctMajMax": 37, "cdProgramCreditsDoctMajMin": 37, "cdProgramCreditsDoctThesis": "24", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The Applied Economics PhD program prepares students for careers in academia, government, and the private sector. All students are required to complete a sequence of courses involving a year-long mathematical treatment of optimization theories and economic models that emphasize cost-benefit analysis. In addition, students will be trained in statistical economic (econometric) models that are used to evaluate and quantify causal theoretical relationships and forecast counterfactual economic outcomes. Required coursework covers price theory for goods and services that trade in competitive and noncompetitive markets as well as the theory of allocation for non-market goods and services. Elective coursework applies these economic and econometric foundations to answer important questions related to food and agriculture, government policy, health, international trade and development, labor, and natural resources and the environment. ", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramGPAGoodStanding": "3", "cdProgramGradMinor4xxx": false, "cdProgramGradResGradProf": "Graduate Research", "cdProgramLOs": "By completing the program, students will build expertise in effectively using microeconomic theory, econometric methods, and other empirical procedures to address real-world social and economic problems.", "cdProgramLengthInTermsGrad": "8", "cdProgramMinorAllowed": true, "cdProgramNameShort": "Appl Econ", "cdProgramReqLanguageGrad": false, "cdProgramReqOther": "Students must also: 
i) pass a written preliminary examination in microeconomic theory;
ii) pass a qualifying research paper requirement;
iii) complete the requirements for two of its six fields or create one individualized field in consultation with their advisor: Agricultural and Food Economics, Health Economics, Labor and Population, Policy Analysis, Resource and Environmental Economics, Trade and Development; 
iv) pass an oral preliminary exam;
v) write a dissertation; and 
vi) pass a final oral exam.", "cdProgramReqSubplanGrad": false, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Doctorate", "cdProgramWebsite": "https://apec.umn.edu/graduate/phd", "feV9J": "<p>The only changes made for this catalog update was to add new courses and update electives to be 2 credit minis so that they stay consistent across specializations.</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Graduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

{"JBsh4": true, "JgOA0": false, "NK1s2": false, "Oin5M": ["All 50 US States and All Territories"], "RF2TB": "Federico Garcia Lammers", "TmgiH": false, "UoHKm": false, "X1TcH": true, "YUCsS": "https://design.umn.edu/academics/programs/architecture/master-architecture", "a3nTH": false, "cdDegreeGrantingCollege": "TALA - College of Design", "cdProgramAcadExchange": false, "cdProgramAccredited": true, "cdProgramAccreditedName": "National Architectural Accrediting Board", "cdProgramAccreditedNextRev": "2024-03-24", "cdProgramAccreditedRevFreq": "Every 8 years", "cdProgramAccreditedWebsite": "https://www.naab.org/", "cdProgramAdmissionEngTestPref": "No Preferred Test", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGPAUgrdMin": "3", "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": true, "cdProgramAdmissionIELTSReadScore": 6.5, "cdProgramAdmissionIELTSTotScore": "6.5", "cdProgramAdmissionIELTSWritScore": 6.5, "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": true, "cdProgramAdmissionTOEFLReadScore": "19", "cdProgramAdmissionTOEFLTotScore": "79", "cdProgramAdmissionTOEFLWritScore": "21", "cdProgramCareer": "Graduate", "cdProgramCreditsDegreeMax": "90", "cdProgramCreditsDegreeMin": "59", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "Architecture encompasses the making and study of the buildings and environments that we inhabit. The concerns of architecture involve a wide variety of areas of study, including the art of representing built projects through drawings and computer graphics; the technology of building structure, building materials, and natural and mechanical systems; the history, theory, and art of making, using, and understanding buildings as cultural artifacts for human use; and the practice of architecture in the context of sustainable environmental systems, urban form, and business economics.

The Master's of Architecture degree is the accredited three-year professional program that prepares students for licensure and practice in the discipline of architecture as a speculative, analytic, and investigative endeavor. Through rigorous methods of inquiry developed in the design studio, lectures, and seminars, students acquire the breadth of knowledge required of the professional architect, including the techniques and processes of representation, communication, and analysis; the history and theory of making architecture and urban form for human use; and the technology, systems, processes, and economics of construction and practice. The 90-credit M.Arch. professional degree program is accredited by the National Architectural Accrediting Board (NAAB). A portfolio for admission is required.

The M.Arch. program is designed to provide rigorous training in the areas of materials and media literacy, stewardship of the built and natural environment, and systemic, urban-scale thinking. M.Arch. students take required coursework in the areas of design studio, building technology, building structures (statics), structural engineering systems (applications), environmental systems, advanced building technology/integrated building systems, technical applications in design, architectural history, design theory, and catalyst workshops. The required curriculum includes integrated design/technology coursework such as the second year graduate design studio and building structures; a net-positive design studio with a focus on daylighting, solar design, and energy conservation in buildings; an advanced studio focused on urban and landscape systems; a two-part global and cultural history sequence; and a Master's Final Project developed independently by the student. Computer tools and applications, as well as analog modes of critical representation, are incorporated into the design studio sequence.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": true, "cdProgramDualDegCredInCommonMax": "24", "cdProgramDualDegMemo": [{"name": "Concurrent M Arch and MS Arch Degree Statement.docx", "path": "files/form/1707270640408/EqoWOtzuGOvw.docx"}, {"name": "MS Arch and MArch Concurrent Plan.pdf", "path": "files/form/1707270862267/RHbhJp4VrnYJ.pdf"}], "cdProgramDualDegTitle": "M.Arch/M.S. Architecture", "cdProgramFieldofStudy": "Art, Design, and the Performing Arts", "cdProgramGPAGoodStanding": "2.800", "cdProgramGradMinor4xxx": false, "cdProgramGradResGradProf": "Graduate Professional", "cdProgramLOs": "<p>This program utilizes learning objectives related to the professional accreditation standards set by the National Architectural Accrediting Board (NAAB).</p>", "cdProgramLengthInTermsGrad": "6", "cdProgramMastPlanA": false, "cdProgramMastPlanB": false, "cdProgramMastPlanC": true, "cdProgramMastPlanCCap": true, "cdProgramMastPlanCCapDesc": "The Master's Final Project is a 10-credit studio-based design exploration under the supervision of a studio faculty mentor.", "cdProgramMastPlanCCrMax": "90", "cdProgramMastPlanCCrMin": "59", "cdProgramMastPlanCHasFinEx": false, "cdProgramMinorAllowed": false, "cdProgramNameShort": "Architect", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": false, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Master's", "cdProgramWebsite": "<p><a href="https://design.umn.edu/academics/programs/architecture/master-architecture" rel="noopener noreferrer nofollow">https://design.umn.edu/academics/programs/architecture/master-architecture</a></p>", "feV9J": "<p>This was primarily a complexity and cost reduction. Courses were offered as A/B term modules. The courses will now be offered as full-term courses which incorporate learning outcomes from the modules. There is some curricular benefit that the faculty considered. Full semester courses allow for more time for integration of key technical and creative concepts in course assignments that are related and build upon each other. The faculty found through review of prior course outcomes that the shorter modular term forced quicker assignments that did not relate well between modules. </p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Graduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active", "yNvRc": "garc0157@umn.edu"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCLA - College of Liberal Arts", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "No", "cdProgramCareer": "Undergraduate", "cdProgramCreditsDegreeMax": "120", "cdProgramCreditsDegreeMin": "120", "cdProgramCreditsProgramMax": "74", "cdProgramCreditsProgramMin": 68, "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The Bachelor of Fine Arts (BFA) is a rigorous and highly selective degree program for students who plan to either pursue a professional career in art and arts-related fields or prepare for specialized graduate study in art. BFA students develop competencies in the technical, theoretical, and intellectual aspects of fine art, cultivating a desire to explore material and media, both conceptual and tangible. BFA students gain a sense of their own aesthetic voice and practice and an ability to speak articulately about the contemporary art world. The program encourages all students to take risks and to engage communities beyond studio and gallery walls and become catalysts for social change.

Faculty in the Department of Art are all active, working artists and thinkers committed to their students and to the diversity of students' histories and experiences. The Bachelor of Fine Arts faculty and curriculum prepare students to become successful studio artists, entrepreneurs, and professionals in the visual arts industry. The program fosters a deep lifetime connection to creating art and creatively and critically engaging in issues of social, environmental, and economic justice.

The program provides shared studio space for every student in their final two semesters of study. Graduates have gone on to receive prestigious grants, to attend the most competitive MFA programs, and to become practicing artists and social change agents of the highest caliber.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Art, Design, and the Performing Arts", "cdProgramLOs": "<p>We utilize University student learning outcomes:</p><ul><li><p>Students can identify, define, and solve problems.</p></li><li><p>Students can locate and critically evaluate information.</p></li><li><p>Students have mastered a body of knowledge and a mode of inquiry.</p></li><li><p>Students understand diverse philosophies and culture within and across societies.</p></li><li><p>Students can communicate effectively.</p></li><li><p>Students understand the role of creativity, innovation, discovery, and expression across disciplines.</p></li><li><p>Students have acquired skills for effective citizenship and lifelong learning.</p></li></ul>", "cdProgramLengthInTermsUndergrad": "8", "cdProgramNameShort": "Art", "cdProgramReqLanguageUgrd": "No second language", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Baccalaureate", "cdProgramWebsite": "<p><a href="https://cla.umn.edu/art" rel="noopener noreferrer nofollow">https://cla.umn.edu/art</a></p>", "cdSamplePlanLink": "<p><a target="_blank" rel="noopener noreferrer nofollow" class="open_in_new_tab" href="https://sampleplan.umn.edu/node/1061">Art B.F.A.</a></p>", "feV9J": "<p>fall 2026 catalog update</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Undergraduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCLA - College of Liberal Arts", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "No", "cdProgramCareer": "Undergraduate", "cdProgramCreditsProgramMax": "24", "cdProgramCreditsProgramMin": "19", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The purpose of a minor is twofold: to indicate competency in a focused area and to complement a major program or primary interest.

The art minor introduces students to the creative process and visual thinking required in art. Students will select core courses from our four areas of study (https://cla.umn.edu/art/about/areas-study) and combine them with courses in art history and concepts in the visuals arts to delve deeper into the theory, ethics, and practice of traditional and contemporary art.

Note: students from any college within the University of Minnesota may minor in art. Many students from other departments or colleges, such as the College of Design, find that an art minor is a valuable complement to their major program.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Art, Design, and the Performing Arts", "cdProgramLOs": "<p>We utilize University student learning outcomes:</p><ul><li><p>Students can identify, define, and solve problems.</p></li><li><p>Students can locate and critically evaluate information.</p></li><li><p>Students have mastered a body of knowledge and a mode of inquiry.</p></li><li><p>Students understand diverse philosophies and culture within and across societies.</p></li><li><p>Students can communicate effectively.</p></li><li><p>Students understand the role of creativity, innovation, discovery, and expression across disciplines.</p></li><li><p>Students have acquired skills for effective citizenship and lifelong learning.</p></li></ul>", "cdProgramMinorType": "Minor related to a major", "cdProgramNameShort": "Art", "cdProgramReqLanguageUgrd": "No second language", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Undergraduate minor", "cdProgramWebsite": "<p><a href="https://cla.umn.edu/art" rel="noopener noreferrer nofollow">https://cla.umn.edu/art</a></p>", "feV9J": "<p>fall 2026 catalog update</p>", "g9JMc": false, "o8EfQ": false, "reportAsNscProgram": false, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCLA - College of Liberal Arts", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "No", "cdProgramCareer": "Undergraduate", "cdProgramCreditsDegreeMax": "120", "cdProgramCreditsDegreeMin": "120", "cdProgramCreditsProgramMin": "34", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "Art history is the study of the human-made world, both past and present. Because images, objects, and the built environment can speak more directly about a culture than its written records, art historians have the chance to analyze societies at their deepest level—including our own highly image-saturated society. Through close, careful study of artworks, images, objects, and sites from across different times, places, and cultures, students in art history acquire a unique understanding of the world and their place within it.

Art history's interdisciplinary curriculum covers not only the fine arts, but also visual and material culture more broadly defined: from paintings and sculpture, to architecture and urban design; from films and photographs, to ceramics and textiles; from scientific illustration and political posters, to performance art and street graffiti. By closely engaging these and other forms of visual expression, students develop crucial skills they can apply in successful careers and meaningful adult lives. These skills include: visual literacy; observational precision; evidence-based argumentation; creative analysis; original and independent research; image-based thinking and communication; and clear and persuasive writing in a variety of modes.

Art history prepares students for professional tracks in: visual arts (e.g., art criticism, art appraisal and sales, art therapy, fashion, interior design, museums, and conservation); the humanities (e.g., grant writing, historic preservation, and philanthropy); media and marketing (e.g., advertising, film, journalism, radio, and television); K-12 and post-secondary education (e.g., art instruction, classroom teaching, and administration); information science and collections management (e.g., libraries and archives in public, non-profit, and corporate contexts); and medicine and law. Thanks to their powerful skill set, students of art history also go on to enjoy higher job satisfaction and lower unemployment rates over the course of their working lives than peers in vocational tracks. Whether or not they pursue careers directly related to art historical study, our alumni are proud to have acquired a highly skilled and well-informed way to look at and learn about the visual and material world.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Art, Design, and the Performing Arts", "cdProgramLOs": "<p>Standard University student learning outcomes, especially:&nbsp;</p><ul><li><p>INNOVATION &amp; CREATIVITY: Students with an Art History major will learn about how artistic forms of knowledge have expressed and transformed social life throughout human history. Likewise, they will learn how history can be studied, researched, and written through creative and innovative research methodologies unlike anywhere else on campus.</p></li><li><p>ENGAGING DIVERSITY: By taking courses that focus on cultures across a wide array of historical eras and geographic areas, as well as on diverse perspectives and identities in our own moment, students with an Art History major engage diversity at every step of their degree completion.</p></li><li><p>COMMUNICATION: Students with an Art History major have the chance to practice and perfect the skill of effective communication in every course they take for the degree. They develop confidence speaking in front of others by venturing their observation-backed ideas in class; they practice writing through the rich and satisfying techniques involved in description; and they develop sophisticated ways to communicate ideas, research, information, and argument through course papers and exams.</p></li><li><p>MASTERY OF KNOWLEDGE: Graduating with an Art History major provides students with an impressive foundation of historical and cultural knowledge about human societies around the world. Many students report that they find it more satisfying to learn information typically associated with other disciplines (e.g., history, media studies, political science, psychology, or social science) through images and objects, allowing for better comprehension and retention on a variety of subjects beyond college.</p></li></ul>", "cdProgramLengthInTermsUndergrad": "8", "cdProgramNameShort": "Art Hist", "cdProgramReqLanguageSemesters": "4", "cdProgramReqLanguageUgrd": "Any second language", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Baccalaureate", "cdProgramWebsite": "<p><a href="https://cla.umn.edu/art-history" rel="noopener noreferrer nofollow">https://cla.umn.edu/art-history</a></p>", "cdSamplePlanLink": "<p><a target="_blank" rel="noopener noreferrer nofollow" class="open_in_new_tab" href="https://sampleplan.umn.edu/node/341">Art History B.A.</a></p>", "feV9J": "<p>fall 2026 catalog update</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Undergraduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

