{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCLA - College of Liberal Arts", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "No", "cdProgramCareer": "Undergraduate", "cdProgramCreditsDegreeMax": "120", "cdProgramCreditsDegreeMin": "120", "cdProgramCreditsProgramMin": "34", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "Linguistics is the study of the human capacity for language. What properties of the human mind allow us to learn and use language in a way that is unique to us as a species? What can the similarities and differences found across human languages tell us about how language is stored and organized in our brains? What role does social context and other nonlinguistic factors play in how humans create meaning with language? 

Natural languages all involve a system of meaning (semantics), a system of externalization through speech or sign (phonology), and a grammatical system of sentence structure that links meaning and externalization (syntax). Students who major in Linguistics gain a strong background in the principles governing the structure of natural languages in all of these areas. Other coursework addresses the role of language in human cognition and social interaction, how languages change over time, computer understanding of natural languages, methods in language documentation and analysis, and other topics.

Coursework and research activities in the Institute of Linguistics give our majors and minors both breadth and depth in linguistics, as well as opportunities to participate in cutting-edge linguistic research. Our graduates take their in-depth knowledge of how language works and their strong problem-solving skills to a variety of careers, including language policy and planning, language teaching, natural language processing and data science, publishing, translation and interpretation, advertising and branding. In addition, coursework in linguistics provides excellent preparation for graduate study in linguistics, NLP and computer science, and professional programs such as law and speech-language-hearing sciences.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Communications, Languages, and Cultural Studies", "cdProgramLOs": "<p>The program utilizes the following University defined student learning outcomes:&nbsp;</p><ul><li><p>Students can identify, define, and solve problems.</p></li><li><p>Students have mastered a body of knowledge and a mode of inquiry.</p></li><li><p>Students can communicate effectively.</p></li></ul>", "cdProgramLengthInTermsUndergrad": "8", "cdProgramNameShort": "Ling", "cdProgramReqLanguageSemesters": "4", "cdProgramReqLanguageUgrd": "Any second language", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Baccalaureate", "cdProgramWebsite": "<p><a href="https://cla.umn.edu/linguistics" rel="noopener noreferrer nofollow">https://cla.umn.edu/linguistics</a></p>", "cdSamplePlanLink": "<p><a target="_blank" rel="noopener noreferrer nofollow" class="open_in_new_tab" href="https://sampleplan.umn.edu/node/1066">Linguistics B.A.</a></p>", "feV9J": "<p>fall 2026 catalog update</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Undergraduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

