{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCOA - College of Food, Agricultural and Natural Resource Sciences", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "No", "cdProgramCareer": "Undergraduate", "cdProgramCreditsDegreeMax": "120", "cdProgramCreditsDegreeMin": "120", "cdProgramCreditsProgramMax": 88, "cdProgramCreditsProgramMin": 75, "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The nutrition major explores how nutrients and the foods from which they are derived aid the body in health, growth, and development. With major national and international concerns for how food and nutrition affect health and disease, registered dietitians and nutritionists have many career opportunities. Students choose one of three options: 1) nutrition studies, 2) the Didactic Program in Dietetics, or 3) nutritional science.

Students expecting to apply to an internship or graduate school should maintain a GPA of at least 3.00. A cumulative GPA of at least 3.30 is highly recommended.

The Didactic Program in Dietetics (DPD) is currently granted accreditation by the Accreditation Council for Education in Nutrition and Dietetics of the Academy of Nutrition and Dietetics, 120 South Riverside Plaza, Suite 2000, Chicago, IL  60606-6995, Phone: 800-877-1600, Website: www.eatright.org.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Math, Engineering, and Science", "cdProgramLOs": "<ul><li><p>Students can locate, critically evaluate, and communicate nutrition research</p></li><li><p>Students will demonstrate a fundamental knowledge of nutrition and how it impacts the health of individuals and communities</p></li><li><p>Students can identify, define, and solve problems related to nutrient deficiencies and excesses</p></li><li><p>Students will understand how social and cultural influences impact nutrition and health</p></li><li><p>Students can identify diverse points of view regarding food systems and nutrition</p></li></ul>", "cdProgramLengthInTermsUndergrad": "8", "cdProgramNameShort": "Nutr", "cdProgramReqLanguageUgrd": "No second language", "cdProgramReqSubplan": true, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Baccalaureate", "cdProgramWebsite": "<p><a href="https://fscn.cfans.umn.edu/undergraduate-programs/nutrition-major" rel="noopener noreferrer nofollow">https://fscn.cfans.umn.edu/undergraduate-programs/nutrition-major</a></p>", "cdSamplePlanLink": "<p><a target="_blank" rel="noopener noreferrer nofollow" class="open_in_new_tab" href="https://sampleplan.umn.edu/node/276">Nutrition B.S.</a></p>", "feV9J": "<p>Changes proposed after the curriculum review by the nutrition undergraduate program. This included consultation with faculty, staff, advisors, and students. The program is adding FSCN 1011 as a Major requirement. Moving Math to a Major Requirement, rather than a sub-plan requirement, removing courses from the Nutritional Sciences subplan that are no longer required for several professional and graduate programs. </p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Undergraduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

