alse, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TMED - Medical School", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionEngTestPref": "No Preferred Test", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": false, "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": false, "cdProgramCareer": "Graduate", "cdProgramCreditsDoctMinorMax": 12, "cdProgramCreditsDoctMinorMin": "12", "cdProgramCreditsMastMinorMax": 9, "cdProgramCreditsMastMinorMin": "9", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "Physiology may be defined as the application of mathematics, physics, and chemistry to the study of structure and function in living systems. As such, physiology is a "hybrid" field in which expertise from many other disciplines is ordinarily required and combined. The program emphasizes a quantitative approach to understanding the functions of cells, organs, and systems in living animals.

The graduate program in the Twin Cities has a cardiovascular emphasis, although many other areas of specialization are represented.

The program includes faculty and corresponding research laboratories from the Department of Integrative Biology and Physiology and also the Departments of Medicine; Surgery; Neuroscience; Neurosurgery; Biochemistry, Molecular Biology, and Biophysics; Pharmacology; Physical Medicine and Rehabilitation; Kinesiology; and Animal Science.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramGPAGoodStanding": "3.500", "cdProgramGradMinor4xxx": true, "cdProgramGradMinorLevel": "Both Masters and Doctoral", "cdProgramLOs": "<p>The Graduate Program in Integrative Biology and Physiology (IBP) believes that training in physiology research starts with a broad educational foundation in the fundamental physiological concepts from molecule, to cell, to organism.</p><p>Students in the IBP Graduate Program will develop and display discipline-specific  competence and knowledge. Specifically, students will:</p><p>1.       Develop core competency in the principles of human physiology.</p><p>2.       Develop a core competency in the principles of cellular physiology.</p><p>3.       Develop skills to design, plan, execute, analyze, and present original and impactful research, particularly as it applies to the student’s thesis project.</p><p>4.       Develop the skill to search, read, and assess/review relevant scientific literature particularly as it applies to the student’s thesis project.</p><p>5.       Develop leadership skills through participation in planning and managing departmental events.</p>", "cdProgramLengthInTermsGrad": "8", "cdProgramMinorType": "Minor related to a major", "cdProgramNameShort": "InBiolPhys", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": true, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Graduate minor", "cdProgramWebsite": "https://med.umn.edu/physiology", "feV9J": "<p>Update IBP minor for Fall 2026.</p>", "g9JMc": false, "o8EfQ": false, "reportAsNscProgram": false, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TNUR - School of Nursing", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionDegreeGrad": "Graduate students come from wide-ranging backgrounds and careers, including nursing, health sciences, nutrition, psychology, physical therapy, social work, public health, and the arts.", "cdProgramAdmissionDegreeUgrd": "The minor is designed for graduate students pursuing healthcare or other majors who are seeking to deepen their understanding of integrative therapies and healing practices.", "cdProgramAdmissionEngTestPref": "No Preferred Test", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": false, "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": false, "cdProgramCareer": "Graduate", "cdProgramCreditsDoctMinorMax": 12, "cdProgramCreditsDoctMinorMin": "12", "cdProgramCreditsMastMinorMax": 8, "cdProgramCreditsMastMinorMin": "8", "cdProgramDeliveryAddl": ["In-person/classroom", "Hybrid", "Completely Online"], "cdProgramDeliveryAddlHybridType": ["Partially Online", "Primarily Online"], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The Minor in Integrative Therapies and Healing Practices is an innovative, interdisciplinary program designed to expose students to a global range of integrative, complementary, cross-cultural, and spiritual healing practices. The program enables students to acquire advanced knowledge and skills to enhance their academic and professional careers, their own lives, and the lives of their patients. Courses augment the preparation of students in health sciences and other disciplines by developing knowledge and skills in the emerging field of integrative healthcare. Specifically, the minor provides students with a theoretical basis for applying integrative therapies and healing practices, prepares students to evaluate research in integrative therapies and healing practices, and prepares students to work collaboratively in a multicultural, pluralistic healthcare system. 

The curriculum includes a core introductory course that provides the theoretical foundation for the minor. Students choose additional courses in clinical applications, spirituality, or cross-cultural health and healing. Students are encouraged to choose these elective credits from courses consistent with their academic training and professional goals. The program draws upon the rich expertise of University and community-based faculty who encourage and challenge students to discover new ways of caregiving and to cultivate diverse skills that will transform their life's work, experiences, and relationships with others. ", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Health Services", "cdProgramGPAGoodStanding": "2.800", "cdProgramGradMinor4xxx": false, "cdProgramGradMinorLevel": "Both Masters and Doctoral", "cdProgramLOs": "This program prepares students to acquire and advance knowledge and skills to enhance their professional careers in healthcare. Benefits of the graduate certificate include: individualized program-based unique learning needs; flexible scheduling options/formats including online and distance learning; faculty and world class researchers, teachers and clinicians; and, community-based learning within healthcare institutions and community organizations.

This graduate minor features interdisciplinary coursework that prepares students to apply theoretical concepts and models to integrative therapies and healing practices; evaluate research in integrative therapies and healing practices; work collaboratively with other healthcare professionals and patients in cross-cultural healthcare systems; use integrative therapies and healing practices; and, engage in experiential, hands-on, and web-based learning.", "cdProgramLengthInTermsGrad": "4", "cdProgramMinorType": "Free-standing minor", "cdProgramNameShort": "IntThpyHlp", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": true, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Graduate minor", "cdProgramWebsite": "<p><a href="https://csh.umn.edu/academics/degrees-minor-and-certificates/graduate-minor" rel="noopener noreferrer nofollow">https://csh.umn.edu/academics/degrees-minor-and-certificates/graduate-minor</a></p>", "feV9J": "<p>Required catalog submission for Fall 2026. Minor edits include updating elective list with new CSPH courses and deleting inactive courses. --EF 2/9/26</p>", "g9JMc": false, "o8EfQ": false, "reportAsNscProgram": false, "sJszy": false, "saaWhifDispAdvr": false, "saaWhifDispPrem": false, "saaWhifDispStd": false, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TIOT - College of Science and Engineering", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": true, "cdProgramAdmissionCourseMin": 6, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "Yes, freshmen and transfer students", "cdProgramCareer": "Undergraduate", "cdProgramCreditsDegreeMax": "120", "cdProgramCreditsDegreeMin": "120", "cdProgramCreditsProgramMin": 91, "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDeliverySite": "NA", "cdProgramDescr": "Earth sciences is the study of the composition, structure, and history of the Earth and of the processes that operate on and within it, with emphasis on the crust, oceans, and atmosphere. The department's programs emphasize applications of physics, chemistry, and biology to understanding the Earth.

Earth scientists are employed in a wide range of fields, including exploration for and development of natural resources (hydrocarbons, minerals, groundwater); environmental science; urban planning; education; and oceanography. Potential employers include the oil, gas, and minerals industries; environmental consultants; federal and private research institutions; universities; schools; and government agencies. An advanced degree is usually required for a career in research or teaching.

Students who earn an Environmental Geosciences B.S. degree may not earn an Earth Sciences B.S. degree.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Math, Engineering, and Science", "cdProgramLOs": "<p>The Department of Earth and Environmental Sciences has defined the following learning outcomes as motivated by the University Student Learning Outcomes. 1) Students will identify, define, and solve a range of fundamental problems in Earth Sciences. 2) Students will demonstrate the ability to locate and collect data relevant to problems in Earth Sciences and to analyze those data in an appropriate manner. 3) Students will demonstrate the ability to apply knowledge of Earth Sciences, including the processes of the integrated Earth system and the history of the Earth system, at an appropriate level of sophistication and rigor. 4) Students will communicate scientific information and ideas effectively to various audiences in appropriate modes (writing, verbally, visually).</p>", "cdProgramLengthInTermsUndergrad": "8", "cdProgramNameShort": "Earth Sci", "cdProgramReqLanguageUgrd": "No second language", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Baccalaureate", "cdProgramWebsite": "<p><a href="https://cse.umn.edu/esci" rel="noopener noreferrer nofollow">cse.umn.edu/esci</a></p>", "cdSamplePlanLink": "<p><a target="_blank" rel="noopener noreferrer nofollow" class="open_in_new_tab" href="https://sampleplan.umn.edu/node/676">Earth Sciences B.S. Earth Sciences</a></p>", "feV9J": "<p>Updates as per Katherine Kvam at the provost level. </p>", "g9JMc": true, "o8EfQ": false, "programLevelCareer": "Undergraduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": true, "cdDegreeGrantingCollege": "TIOT - College of Science and Engineering", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionDegreeUgrd": "A bachelor's degree in geology, geophysics, earth and material sciences, chemistry, physics, biology, or environmental science. ", "cdProgramAdmissionEngTestPref": "No Preferred Test", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGPAUgrdMin": "3", "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": true, "cdProgramAdmissionIELTSTotScore": "6.5", "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOthAppReqs": "Materials for a complete application file include the student's statement of purpose, optional diversity statement, three letters of recommendation, transcripts, and the Application for Admission. Applications are considered at any time; however, to be considered for financial aid, all materials must be submitted by December 15. Studies may begin in any semester or summer session, although fall semester is preferable. ", "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": true, "cdProgramAdmissionTOEFLReadScore": 4.5, "cdProgramAdmissionTOEFLTotScore": 4.5, "cdProgramAdmissionTOEFLWritScore": 4.5, "cdProgramCareer": "Graduate", "cdProgramCreditsDegreeMin": "30", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The modern earth sciences are a remarkable synthesis of the physical and biological sciences. They are at the forefront of inquiry into and solutions of most of the major issues involving the global environment: climate, oceans, freshwater in all its forms, natural resources, and natural disasters. Like no other field, they integrate all the systems, from surface to great depth, from physics to chemistry to biology, and over all of geologic time and all geographic scales. The program includes the fields of structural geology, tectonics, petrology, hydrogeology, geomorphology, sedimentology, surface processes, geochemistry, geobiochemistry, geobiology, paleontology and paleobiology, chemical oceanography, mineralogy, mineral and rock magnetism, rock and mineral physics, geodynamics, seismology, geostatistics, planetary geology, and geophysics and applied geophysics. 

Students complete one of the following tracks: Geology, Geophysics, Biogeology, Hydrogeology, or Earth Sciences.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Math, Engineering, and Science", "cdProgramGPAGoodStanding": "2.800", "cdProgramGradMinor4xxx": true, "cdProgramGradResGradProf": "Graduate Research", "cdProgramLOs": "<p>-demonstrate advanced knowledge in core areas of earth sciences<br>-communicate effectively across disciplines and with a range of audiences<br>-understand ethical norms and conduct research with integrity<br>-possess the skills necessary for collaborative teamwork and leadership roles in academia, industry, or related fields</p>", "cdProgramLengthInTermsGrad": "4", "cdProgramMastPlanA": true, "cdProgramMastPlanACrMax": 20, "cdProgramMastPlanACrMin": 20, "cdProgramMastPlanACrThesis": "10", "cdProgramMastPlanAFinExDesc": "Oral examination only", "cdProgramMastPlanB": true, "cdProgramMastPlanBCap": true, "cdProgramMastPlanBCapDescr": "The Plan B project comprises one or more projects such as a research paper, presentation of research results, and/or completion of a faculty-supervised research experience.
", "cdProgramMastPlanBCrMax": 30, "cdProgramMastPlanBCrMin": 30, "cdProgramMastPlanBFinEx": "Written and oral examinations", "cdProgramMastPlanC": true, "cdProgramMastPlanCCap": false, "cdProgramMastPlanCCrMax": 30, "cdProgramMastPlanCCrMin": 30, "cdProgramMastPlanCHasFinEx": false, "cdProgramMinorAllowed": true, "cdProgramNameShort": "Earth Sci", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": true, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Master's", "cdProgramWebsite": "https://cse.umn.edu/esci", "feV9J": "<p>There is more interest for coursework-only degrees for non-hydrologists, and some students need the option of a coursework-only degree. We had a discussion at the last faculty meeting and everybody agreed this was a good idea.</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Graduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "splitOwnership": false, "status": "Active"}

