ompleteVariableCoursesAndVariableCredits", "id": "cmrpkLfY", "maxCredits": 20, "minCourses": 0, "minCredits": 0, "name": "Norwegian", "value": {"condition": "courses", "id": "z9d7H73O", "subSelections": [], "values": [{"logic": "and", "value": ["0084601"]}, {"logic": "and", "value": ["0084611"]}, {"logic": "and", "value": ["0084641"]}, {"logic": "and", "value": ["0084661"]}]}}, {"condition": "completeVariableCoursesAndVariableCredits", "id": "zkAgAGEX", "maxCredits": 20, "minCourses": 0, "minCredits": 0, "name": "Swedish", "value": {"condition": "courses", "id": "kc7B8mAz", "subSelections": [], "values": [{"logic": "and", "value": ["0084931"]}, {"logic": "and", "value": ["0084941"]}, {"logic": "and", "value": ["0084951"]}, {"logic": "and", "value": ["0084961"]}]}}]}], "showInCatalog": true, "sisId": "", "type": "Completion Requirements"}, {"id": "82638", "name": "German", "notes": "<p><br></p>", "requirementLevel": "programSubPlanRequirements", "rules": [{"condition": "freeformText", "id": "28aSoCDp", "name": "German", "value": "The German sub-plan requires a minimum of 18 credits. Students who choose this sub-plan will take a minimum of 33 credits toward the German, Scandinavian, and Dutch B.A.

Students who choose to complete the German sub-plan/emphasis must fulfill all three competencies (Advanced Language; Language & Textual Analysis; Critical Literacy & Global Understanding) with GER courses. Additionally, at least 3 of the 5 required electives must also be GER. If a 5xxx course is chosen as the senior capstone, it must be a GER 5xxx. The major program must be approved by the director of undergraduate studies."}], "showInCatalog": true, "sisId": "", "type": "Completion Requirements"}, {"id": "82639", "name": "Scandinavian & Finnish", "requirementLevel": "programSubPlanRequirements", "rules": [{"condition": "freeformText", "id": "bBLQfeO2", "name": "Scandinavian & Finnish", "value": "The Scandinavian & Finnish sub-plan requires a minimum of 18 credits. Students who choose this sub-plan will take a minimum of 33 credits toward the German, Scandinavian, and Dutch B.A.


Students who choose to complete the Scandinavian & Finnish sub-plan/emphasis must fulfill all three competencies (Advanced Language; Language & Textual Analysis; Critical Literacy & Global Understanding) with SCAN or FIN 3xxx or SCAN 5xxx courses. Additionally, at least 3 of the 5 required electives must also be SCAN or FIN 3xxx, or SCAN 5xxx. If a 5xxx course is chosen as the senior capstone, it must be a SCAN 5xxx course. The major program must be approved by the director of undergraduate studies."}], "showInCatalog": true, "sisId": "", "type": "Completion Requirements"}]}

