{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TIOT - College of Science and Engineering", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionDegreeUgrd": "Applicants must have a bachelor's degree from an accredited college or university in an engineering field, computer science, physics, or mathematics.", "cdProgramAdmissionEngTestPref": "No Preferred Test", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGPAUgrdMin": "3", "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": true, "cdProgramAdmissionIELTSReadScore": "6.5", "cdProgramAdmissionIELTSTotScore": "6.5", "cdProgramAdmissionIELTSWritScore": "6.5", "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOthAppReqs": "Applications are accepted on a rolling basis.", "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": true, "cdProgramAdmissionTOEFLReadScore": "19", "cdProgramAdmissionTOEFLTotScore": "79", "cdProgramAdmissionTOEFLWritScore": "21", "cdProgramCareer": "Graduate", "cdProgramCreditsDegreeMax": "31", "cdProgramCreditsDegreeMin": "31", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The Robotics MS program provides a strong foundation in robotics by gathering in a single program the relevant knowledge, expertise, and educational assets such as robot modeling and control, perception using cameras and other sensors, and cognition to reason, plan, and make decisions.

Students who graduate from this regular 2-year master's program will learn the state-of-the-art methods for developing and using robots, be exposed to the cutting-edge technologies and theory forming the basis for the next generation of robots and their applications in areas such as agriculture, underwater exploration, autonomous driving, and manufacturing applications. ", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Math, Engineering, and Science", "cdProgramGPAGoodStanding": "3.000", "cdProgramGradMinor4xxx": false, "cdProgramGradResGradProf": "Graduate Research", "cdProgramLOs": "<p>The expected skillset for a graduate student in robotics:</p><ul><li><p>demonstrate basic proficiency with the three key areas of robotics theory: (1) cognition, (2) perception, (3) robot modeling and control</p></li><li><p>accrue significant applied experience in robotics through project-based learning</p></li><li><p>function on and lead multi-disciplinary teams for collaborative work</p></li><li><p>communicate robotics concepts effectively in both academic and industrial settings</p></li><li><p>show excellent scholarship in a cutting-edge area of robotics through independent robotics research</p></li><li><p>use research and methodology practices consistent with the highest academic standards</p></li><li><p>understand and apply ethical norms in research and practice</p></li></ul>", "cdProgramLengthInTermsGrad": "6", "cdProgramMastPlanA": true, "cdProgramMastPlanACrMax": "21", "cdProgramMastPlanACrMin": "21", "cdProgramMastPlanACrThesis": "10", "cdProgramMastPlanAFinExDesc": "Oral examination only", "cdProgramMastPlanB": true, "cdProgramMastPlanBCap": true, "cdProgramMastPlanBCapDescr": "The capstone project is completed in consultation with the faculty, or in collaboration with industry partners.  

", "cdProgramMastPlanBCrMax": "31", "cdProgramMastPlanBCrMin": "31", "cdProgramMastPlanBFinEx": "Written and oral examinations", "cdProgramMastPlanC": true, "cdProgramMastPlanCCap": true, "cdProgramMastPlanCCapDesc": "Plan C students must complete, in consultation with the advisor, one class project totaling 100 hours or two projects of 50 hours each.", "cdProgramMastPlanCCrMax": "31", "cdProgramMastPlanCCrMin": "31", "cdProgramMastPlanCHasFinEx": false, "cdProgramMinorAllowed": true, "cdProgramNameShort": "Robotics", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": false, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Master's", "cdProgramWebsite": "https://cse.umn.edu/mnri", "feV9J": "<p>2026-28 catalog update.</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Graduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": false, "saaWhifDispPrem": false, "saaWhifDispStd": false, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCLA - College of Liberal Arts", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "No", "cdProgramCareer": "Undergraduate", "cdProgramCreditsProgramMin": 14, "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The Museum & Curatorial Studies Minor invites students from diverse majors to engage in the study of museum history and practices including curating, managing collections, and designing exhibitions. The minor provides a foundation of museum history and theory spanning multiple disciplines, while also supplying exposure to museum careers and the skills that sustain them. Professional training through an internship at a local museum, gallery, or archive is a requirement of the minor.

The MCS minor addresses students and future professionals across the arts, humanities, and social, biological, and physical sciences. The methods of collecting and organizing objects for display are shared among the museum institutions, whether they focus on arts, sciences, history, or culture. Indeed, collections of natural history and visual culture have been entwined since the premodern era, and our contemporary museum culture continues to tell stories about the interconnected world. As such, this minor reveals connectivity across fields to demonstrate the shared work of museums to preserve and present all forms of knowledge and culture, whether botanical specimens, ancient sculpture, Hmong textiles, or video art.

Through a rigorous combination of coursework and professional experience, this program prepares students for graduate school and/or entry level positions in museums, galleries, and archives. Electives and internships will provide students with opportunities to learn skills such as the collection of object-based data, digital documentation, cataloging objects, and the use of digital tools for spatial planning. They will also learn to conduct scholarly research and to write clearly and concisely for a range of different audiences. Skills learned through the minor’s curriculum contribute to career readiness for a range of fields, including but not limited to: design, digital communication, writing and journalism, collection management, intellectual property, education, and administration.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramLOs": "<p>Standard University student learning outcomes, especially:&nbsp;</p><ul><li><p>INNOVATION &amp; CREATIVITY: Students with an MCS minor will learn about how artistic, scientific, and other forms of knowledge innovation are able to impact public life through strategies of museum collection, preservation, and display.</p></li><li><p>PROBLEM SOLVING: Through coursework and applied, internship-based learning,&nbsp; students with an MCS minor will learn about the major goals and challenges related to object collections and display, while also developing fluency in the research-based strategies for meeting those objectives.</p></li><li><p>ACTIVE CITIZENSHIP: Students with an MCS minor will learn about how and why museums have served a major role in public, democratic life for centuries; they will gain fluency in the creative, professional careers that sustain museums today; and they will develop a critical lens by which to analyze museum activities in contemporary society.&nbsp;</p></li><li><p>ENGAGING DIVERSITY: Because museums are so often sites for cultural preservation, because they supply opportunities for cross-cultural encounter, and because they require the skill of cultural competency from its career professionals, museums offer students with an MCS minor an active site through which to engage diversity.</p></li></ul>", "cdProgramMinorType": "Free-standing minor", "cdProgramNameShort": "MuseCurato", "cdProgramReqLanguageUgrd": "No second language", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Undergraduate minor", "cdProgramWebsite": "<p><a target="_blank" rel="noopener noreferrer nofollow" class="open_in_new_tab" href="https://cla.umn.edu/art-history/undergraduate/majors-minor/undergraduate-minor-museum-curatorial-studies">https://cla.umn.edu/art-history/undergraduate/majors-minor/undergraduate-minor-museum-curatorial-studies</a></p>", "feV9J": "<p>adding newly approved courses to the appropriate buckets.</p>", "g9JMc": false, "o8EfQ": false, "reportAsNscProgram": false, "sJszy": false, "saaWhifDispAdvr": false, "saaWhifDispPrem": false, "saaWhifDispStd": false, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": true, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCED - College of Education and Human Development", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionEngTestPref": "No Preferred Test", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": false, "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOthAppReqs": "Students interested in the minor are strongly encouraged to confer with their major field advisor and director of graduate studies, and the Special Education Coordinator regarding feasibility and requirements. 

Students enrolled in the Special Education MEd or Special Education ILP MEd programs are not eligible for the minor.

Students with an Educational Psychology major may elect a minor in Special Education, but no courses may count for both the major and the minor.", "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": false, "cdProgramCareer": "Graduate", "cdProgramCreditsMastMinorMax": 12, "cdProgramCreditsMastMinorMin": "12", "cdProgramDeliveryAddl": ["Hybrid"], "cdProgramDeliveryAddlHybridType": ["Primarily Online"], "cdProgramDeliveryPrimary": "Hybrid", "cdProgramDeliveryPrimaryHybridType": "Primarily Online", "cdProgramDescr": "The Special Education minor is a 12-credit program that provides a deeper understanding of special needs populations both inside and outside of teaching. Students will gain an understanding of the foundations of special education through a provision of special education services to children from birth through age 22. The field of special education as it relates to children of diverse backgrounds is infused throughout the coursework. Emphasis includes implementing evidence-based practices by examining students' areas of strength and challenges and using data to determine effective academic, functional, and social-emotional treatment plans to ensure that persons with special needs meet their full potential. The Special Education minor is designed to meet the needs of students who are interested in working with children including those interested in elementary and secondary teaching, counseling, family social science, social work, occupational and physical therapy, mental health professionals, and those interested in neuroscience fields among others.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramGPAGoodStanding": "3.000", "cdProgramGradMinor4xxx": false, "cdProgramGradMinorLevel": "Masters", "cdProgramLOs": "The learning outcomes for the Special Education Minor include being able to identify, define and solve problems around the needs of children with special needs.", "cdProgramLengthInTermsGrad": "8", "cdProgramMinorType": "Free-standing minor", "cdProgramNameShort": "Spec Educ", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": true, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Graduate minor", "cdProgramWebsite": "<p><a target="_blank" rel="noopener noreferrer" class="open_in_new_tab" href="https://edpsych.umn.edu/academics/special-education/graduate-minor">https://edpsych.umn.edu/academics/special-education/graduate-minor</a></p>", "feV9J": "<p>The reason for these changes is that our coursework offerings and modalities have been updated to align with the same offerings in our Special Education M.Ed. program, to ensure quality and efficiency. These revisions will have no impact on the department’s annual budgeting aside from some cost savings that may be realized by removing EPSY 5015 which was part of a consolidation effort of multiple versions of courses offered to different programs such that only EPSY 5016 is offered moving forward. Further, there is no impact on planning needs in the context of the mission of the department and college as the modality change is already available as an option.</p>", "g9JMc": false, "o8EfQ": true, "reportAsNscProgram": false, "s4fIZ": "Coursework offerings and modalities have been updated to align with the same offerings in our Special Education M.Ed. program, to ensure quality and efficiency. ", "sJszy": false, "saaWhifDispAdvr": false, "saaWhifDispPrem": false, "saaWhifDispStd": false, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCLA - College of Liberal Arts", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionCourseCreditMin": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionPreMajorStatus": "No", "cdProgramCareer": "Undergraduate", "cdProgramCreditsDegreeMin": "120", "cdProgramCreditsProgramMin": "31", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The goal of the Dakota language major is to best situate both heritage and non-heritage Dakota students to be able to positively intervene in the cultural life of the state's Dakota communities by contributing to the revitalization of the Dakota language. As a land grant institution, the University has a mission to contribute to the state's communities, and the major will help fulfill that mission. The department also prioritizes local American Indian community engagement and advocacy. 

One of the single best ways to create positive change within our communities is to instill pride and celebrate cultural traditions like language at an early age. What distinguishes this program from any other is our communication-centered approach based in storytelling and Dakota lifeways and knowledge in addition to using both academically rigorous grammatical instruction and immersion techniques inside the classroom. This method has proven to be a very powerful combination in helping our students reach a high level of proficiency in the Dakota language. Students who complete the program to attain this high proficiency will have the foundational skills to contribute to Dakota language community building by bringing the Dakota language back into the home, to go into the high-demand field of immersion teaching, and to work in language preservation programs. With this major, students will: 

1) Be more prepared to fill an ever-growing need for immersion teacher positions; 2) Graduate with a more sophisticated knowledge of the Dakota language in general; 3) Graduate with the prestige that comes of having earned a bachelor's degree in the Dakota language; 4) Have more time to increase their fluency under instructor supervision; 5) Increase their knowledge of immersion pedagogy; and 6) Earn a bachelor's degree in the Dakota language (rather than a certificate) thereby increasing both their Dakota language credentials and earning potential upon graduation.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Communications, Languages, and Cultural Studies", "cdProgramLOs": "<p>American Indian Studies utilizes departmental program learning outcomes.</p><p>1.	 Sovereignty: Students will understand how sovereignty is a spiritual, moral, and dynamic cultural force that empowers Indigenous individuals and their nations to act socially and politically as self-determining agents in the world.</p><p>2.	Diversity of Native and Indigenous Knowledge:	Students will engage the diversity of philosophies and cultures of Native people in North America and/or of Indigenous people across the world. Students will understand American Indian Studies as an interdisciplinary field of knowledge that affirms, reflects on, and synthesizes ways of knowing that exist among Native and Indigenous peoples.</p><p>3.	Resurgence and Revitalization: Students will recognize the continuity and revitalization of Native/Indigenous thought, language, and political and social identities over time and into the present. Students will identify how Indigenous values and ethics inform the types of justice Native and Indigenous peoples seek for their communities</p><p>4.&nbsp; &nbsp; Being a Good Relative: Students will acquire skills to help them think about both Native/Indigenous nations and society at large. Students will accept responsibility to communicate what they have learned verbally, in writing, and/or through other forms of media.</p>", "cdProgramLengthInTermsUndergrad": "8", "cdProgramNameShort": "Dakota Lng", "cdProgramReqLanguageSemesters": "4", "cdProgramReqLanguageSpecific": "Dakota", "cdProgramReqLanguageUgrd": "Specific second languages", "cdProgramReqSubplan": false, "cdProgramStatus": "Active", "cdProgramSumTerms": false, "cdProgramTypeManual": "Baccalaureate", "cdProgramWebsite": "<p><a href="https://cla.umn.edu/ais" rel="noopener noreferrer nofollow">https://cla.umn.edu/ais</a></p>", "cdSamplePlanLink": "<p><a href="https://sampleplan.umn.edu/node/401" class="open_in_new_tab" rel="noopener noreferrer nofollow">https://sampleplan.umn.edu/node/401</a></p>", "feV9J": "<p>fall 2026 catalog update</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Undergraduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": false, "saaWhifDispPrem": false, "saaWhifDispStd": false, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TCED - College of Education and Human Development", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionEngTestPref": "Test of English as a Foreign language (TOEFL)", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGPAUgrdMin": "2.8", "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": true, "cdProgramAdmissionIELTSReadScore": "6.5", "cdProgramAdmissionIELTSTotScore": "6.5", "cdProgramAdmissionIELTSWritScore": "6.5", "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": true, "cdProgramAdmissionTOEFLReadScore": "19", "cdProgramAdmissionTOEFLTotScore": "79", "cdProgramAdmissionTOEFLWritScore": "21", "cdProgramCareer": "Graduate", "cdProgramCreditsDegreeMax": "34", "cdProgramCreditsDegreeMin": "31", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDeliverySite": "NA", "cdProgramDescr": "This non-licensure M.Ed. provides students with a robust preparation for work in the field of early childhood education. The degree combines coursework in cutting-edge child development research with opportunities to engage in supervised applied work with young children and options to create individualized areas of study. This M.Ed. is an excellent opportunity for students who are interested in combining developmental science and individualized learning options free from the requirements of Minnesota state teaching license requirements. It is ideal for students who want to be leaders in the early childhood field outside of the Minnesota public school system. ", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Education", "cdProgramGPAGoodStanding": "2.800", "cdProgramGradMinor4xxx": true, "cdProgramGradResGradProf": "Graduate Professional", "cdProgramLOs": "The Early Care and Education M.Ed program uses both learning outcomes designed by the university and a program-specific learning outcome. The program-specific outcome is described below: 

Graduates of the Early Childhood Education program will be able to understand how children learn and develop, and provide learning opportunities that support children’s physical, intellectual, social and personal development. 

This standard is aligned with the InTASC Standard #1: Learner Development. North Dakota Common Metrics: Skills of Teaching Observation Tool (STOT). Full rubric is outlined below. ", "cdProgramLengthInTermsGrad": 3, "cdProgramMastPlanA": false, "cdProgramMastPlanB": false, "cdProgramMastPlanC": true, "cdProgramMastPlanCCap": false, "cdProgramMastPlanCCrMax": 34, "cdProgramMastPlanCCrMin": 31, "cdProgramMastPlanCHasFinEx": false, "cdProgramMinorAllowed": true, "cdProgramNameShort": "ErlyCareEd", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": false, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Master's", "cdProgramWebsite": "<p><a target="_blank" rel="noopener noreferrer" class="open_in_new_tab" href="https://icd.umn.edu/academics/early-care-education/masters-education">https://icd.umn.edu/academics/early-care-education/masters-education</a></p>", "feV9J": "<p>Fall 2026 catalog review</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Graduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": false, "saaWhifDispPrem": false, "saaWhifDispStd": false, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TPUB - School of Public Health", "cdProgramAcadExchange": false, "cdProgramAccredited": true, "cdProgramAccreditedName": "Applied and Natural Science Accreditation Commission of ABET (ABET)", "cdProgramAccreditedNextRev": "2026-07-01", "cdProgramAccreditedRevFreq": "Every 6 years", "cdProgramAccreditedWebsite": "https://www.abet.org/", "cdProgramAdmissionEngTestPref": "No Preferred Test", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGPAUgrdMin": "3", "cdProgramAdmissionGRE": false, "cdProgramAdmissionIELTS": true, "cdProgramAdmissionIELTSTotScore": "7", "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOthAppReqs": "For TOEFL exams taken before January 21, 2026: Minimum total score is 100
For TOEFL exams taken on or after January 21, 2026: Minimum total score is 5

Occupational Hygiene MS admission requires undergraduate coursework in human biology, organic chemistry, physics, and college-level mathematics. For applicants with occupational/industrial hygiene work experience, undergraduate coursework in at least three of these subjects is required .", "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": true, "cdProgramAdmissionTOEFLTotScore": 5, "cdProgramCareer": "Graduate", "cdProgramCreditsDegreeMax": 48, "cdProgramCreditsDegreeMin": 48, "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The Occupational Hygiene program focuses on the health and safety of people at work, the community at large, and the environment. Specific concerns are with the recognition, evaluation and control of potential workplace hazards, including chemical, physical, and biological agents. To complete program requirements, students will choose electives, in consultation with their academic advisor, which may include credits towards a minor.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Health Services", "cdProgramGPAGoodStanding": "3", "cdProgramGradMinor4xxx": true, "cdProgramGradResGradProf": "Graduate Research", "cdProgramLOs": "<p>The Council on the Education of Public Health (CEPH) is the accrediting body for the School of Public Health, and has assessment requirements for accreditation including the following areas of foundational knowledge. The School is in good standing on these assessment measures and was reaccredited in April 2022.<br><br>1. Explain public health history, philosophy and values  <br>2. Identify the core functions of public health and the 10 Essential Services  <br>3. Explain the role of quantitative and qualitative methods and sciences in describing and assessing a population’s health   <br>4. List major causes and trends of morbidity and mortality in the US or other community relevant to the school or program  <br>5. Discuss the science of primary, secondary and tertiary prevention in population health, including health promotion, screening, etc.  <br>6. Explain the critical importance of evidence in advancing public health knowledge   <br>7. Explain effects of environmental factors on a population’s health  <br>8. Explain biological and genetic factors that affect a population’s health  <br>9. Explain behavioral and psychological factors that affect a population’s health  <br>10. Explain the social, political and economic determinants of health and how they contribute to population health and health inequities  <br>11. Explain how globalization affects global burdens of disease  <br>12. Explain an ecological perspective on the connections among human health, animal health and ecosystem health (e.g., One Health) </p>", "cdProgramLengthInTermsGrad": 4, "cdProgramMastPlanA": false, "cdProgramMastPlanB": true, "cdProgramMastPlanBCap": true, "cdProgramMastPlanBCapDescr": "Students must complete a written plan B project where they are required to synthesize and integrate knowledge acquired in coursework and other learning experiences and apply theory and principles in a context that reflects an aspect of professional practice. The Plan B Project will be used as a means by which faculty judge whether the student has mastered the body of knowledge and can demonstrate proficiency in the required competencies through written and oral presentation. All master's degree candidates are required to pass a final oral examination to be taken after submission of the Plan B project(s).", "cdProgramMastPlanBCrMax": 48, "cdProgramMastPlanBCrMin": 48, "cdProgramMastPlanBFinEx": "Oral examination only", "cdProgramMastPlanC": false, "cdProgramMinorAllowed": true, "cdProgramNameShort": "Plan B", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": false, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Master's", "cdProgramWebsite": "<p>www.sph.umn.edu</p>", "feV9J": "<p>Every two years programs must submit a new proposal, this serves as the proposal for Fall 2026. This proposal reflects no changes to the current curriculum for the Occupational Hygiene MS.</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Graduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": false, "saaWhifDispPrem": false, "saaWhifDispStd": false, "splitOwnership": false, "status": "Active"}

{"JBsh4": false, "JgOA0": false, "NK1s2": false, "TmgiH": false, "UoHKm": false, "X1TcH": true, "a3nTH": false, "cdDegreeGrantingCollege": "TVET - College of Veterinary Medicine", "cdProgramAcadExchange": false, "cdProgramAccredited": false, "cdProgramAdmissionDegreeUgrd": "A bachelor's degree in a biological or basic science is required. Previous laboratory experience is strongly preferred.", "cdProgramAdmissionEngTestPref": "Test of English as a Foreign language (TOEFL)", "cdProgramAdmissionGMAT": false, "cdProgramAdmissionGPACollAdmit": false, "cdProgramAdmissionGPATrans": false, "cdProgramAdmissionGPATransIUT": false, "cdProgramAdmissionGPAUgrdMin": "3.25", "cdProgramAdmissionGRE": true, "cdProgramAdmissionIELTS": true, "cdProgramAdmissionIELTSReadScore": "6.5", "cdProgramAdmissionIELTSTotScore": "6.5", "cdProgramAdmissionIELTSWritScore": "6.5", "cdProgramAdmissionLSAT": false, "cdProgramAdmissionMCAT": false, "cdProgramAdmissionOthAppReqs": "Submission of all application materials by December 1 is required to ensure consideration for fall semester admission.  https://www.vetmed.umn.edu/education-training/ms-phd-programs/ms-phd-comparative-and-molecular-biosciences", "cdProgramAdmissionOtherTest": false, "cdProgramAdmissionTOEFL": true, "cdProgramAdmissionTOEFLReadScore": "19", "cdProgramAdmissionTOEFLTotScore": "79", "cdProgramAdmissionTOEFLWritScore": "21", "cdProgramCareer": "Graduate", "cdProgramCreditsDegreeMin": "30", "cdProgramDeliveryAddl": ["In-person/classroom"], "cdProgramDeliveryAddlHybridType": [], "cdProgramDeliveryPrimary": "In-person/classroom", "cdProgramDescr": "The mission of the Comparative and Molecular Biosciences (CMB) program is to train outstanding scientists in the basic mechanisms of animal and human health and disease. The CMB program embraces a One Health approach and investigates a wide range of species, including humans, laboratory animals, companion animals, and livestock species. 

The CMB program is transdisciplinary, bringing together basic, applied, and clinical scientists from a number of departments to provide students with individualized, cutting-edge biomedical research training. Areas of emphasis include genetic and infectious diseases and comparative aspects of biology and pathology across animal species and humans. Students receive scientific training that prepares them for careers as independent investigators and educators in academia, industry, and government.  

The purpose of the master's degree is to provide technical training and scientific competence in the basic mechanisms of animal and human health and disease.", "cdProgramDisplayCatalog": true, "cdProgramDualDeg": false, "cdProgramFieldofStudy": "Math, Engineering, and Science", "cdProgramGPAGoodStanding": "3.000", "cdProgramGradMinor4xxx": false, "cdProgramGradResGradProf": "Graduate Research", "cdProgramLOs": "Our students achieve scientific acuity and technical excellence through high quality impactful mentored thesis research, supplemented through rigorous core coursework. Research is based on the One Health principle, working at the intersections of animal, human, and ecosystem health. Our students work closely with faculty and peers in a diverse, supportive, and collaborative environment to develop the critical thinking, technical, and communication skills for successful careers in academia, private industries, or the public sector.", "cdProgramLengthInTermsGrad": "4", "cdProgramMastPlanA": true, "cdProgramMastPlanACrMax": "20", "cdProgramMastPlanACrMin": "20", "cdProgramMastPlanACrThesis": "10", "cdProgramMastPlanAFinExDesc": "Written and oral examinations", "cdProgramMastPlanB": false, "cdProgramMastPlanC": false, "cdProgramMinorAllowed": true, "cdProgramNameShort": "CompMolBio", "cdProgramReqLanguageGrad": false, "cdProgramReqSubplanGrad": false, "cdProgramStatus": "Active", "cdProgramSubplanMoreThanOne": false, "cdProgramSumTerms": false, "cdProgramTypeManual": "Master's", "cdProgramWebsite": "<p><a href="https://vetmed.umn.edu/graduate-programs/ms-phd-comparative-and-molecular-biosciences" rel="noopener noreferrer nofollow">https://vetmed.umn.edu/graduate-programs/ms-phd-comparative-and-molecular-biosciences</a></p>", "feV9J": "<p>no changes, 2026 catalog submission</p>", "g9JMc": false, "o8EfQ": false, "programLevelCareer": "Graduate", "reportAsNscProgram": true, "sJszy": false, "saaWhifDispAdvr": true, "saaWhifDispPrem": true, "saaWhifDispStd": true, "sp